INSERT OR IGNORE INTO trait_question_meta_v1 (question_id, slug, public_question, what_counts, metadata_line, homepage_eligible, share_preview, active, created_at) VALUES
  ('lebron-james-2011-clutch', '2011-lebron-clutch-in-the-finals', 'Was 2011 Finals LeBron clutch?', 'You want the last shot in his hands. So does he.', 'LeBron James · 2010-11 Heat', 1, '2011 LEBRON · CLUTCH IN THE FINALS?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('nikola-jokic-2023-team-defender', '2023-jokic-good-team-defender', 'Was champion Jokic actually a good team defender?', 'Elite at rotations, communication, help, hands in the lane.', 'Nikola Jokic · 2022-23 Nuggets', 1, '2023 JOKIC · GOOD TEAM DEFENDER?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('rudy-gobert-2022-switchable-defender', '2022-gobert-hold-up-on-a-switch', 'Could DPOY Gobert hold up switched onto a guard?', 'Takes the switch, guard through big, and holds up.', 'Rudy Gobert · 2021-22 Jazz', 1, '2022 GOBERT · HOLD UP ON A SWITCH?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('james-harden-2018-foul-merchant', '2018-harden-foul-merchant', 'Was MVP Harden a foul merchant?', 'Hunts contact to draw whistles more than to score.', 'James Harden · 2017-18 Rockets', 1, '2018 HARDEN · FOUL MERCHANT?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('trae-young-2022-foul-merchant', '2022-trae-foul-merchant', 'Was 2022 Trae Young a foul merchant?', 'Hunts contact to draw whistles more than to score.', 'Trae Young · 2021-22 Hawks', 1, '2022 TRAE · FOUL MERCHANT?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
