  ('kobe-bryant-2006-clutch', '2006-kobe-actually-clutch', 'Was 81-point Kobe actually clutch?', 'You want the last shot in his hands. So does he.', 'Kobe Bryant · 2005-06 Lakers', 1, '2006 KOBE · ACTUALLY CLUTCH?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('shaquille-o-neal-2000-clutch', '2000-shaq-clutch-late', 'Was MVP Shaq clutch with the game on the line?', 'You want the last shot in his hands. So does he.', 'Shaquille O''Neal · 1999-00 Lakers', 1, '2000 SHAQ · CLUTCH LATE?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
