  ('robert-horry-2002-clutch', '2002-horry-big-shot-bob', 'Was Big Shot Bob really that clutch?', 'You want the last shot in his hands. So does he.', 'Robert Horry · 2001-02 Lakers', 1, '2002 HORRY · BIG SHOT BOB?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('demar-derozan-2022-clutch', '2022-derozan-best-clutch-scorer', 'Was 2022 DeRozan the best clutch scorer in the league?', 'You want the last shot in his hands. So does he.', 'DeMar DeRozan · 2021-22 Bulls', 1, '2022 DEROZAN · BEST CLUTCH SCORER?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
