  ('kyrie-irving-2022-off-court-knucklehead', '2022-kyrie-threat-to-his-own-team', 'Was 2022 Kyrie a threat to his own team?', 'Had severe off-court issues that could threaten the team''s success.', 'Kyrie Irving · 2021-22 Nets', 1, '2022 KYRIE · THREAT TO HIS OWN TEAM?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('draymond-green-2023-off-court-knucklehead', '2023-draymond-threat-to-his-own-team', 'Was 2023 Draymond a threat to his own team?', 'Had severe off-court issues that could threaten the team''s success.', 'Draymond Green · 2022-23 Warriors', 1, '2023 DRAYMOND · THREAT TO HIS OWN TEAM?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('dennis-rodman-1996-off-court-knucklehead', '1996-rodman-threat-to-his-own-team', 'Was 72-win Rodman a threat to his own team?', 'Had severe off-court issues that could threaten the team''s success.', 'Dennis Rodman · 1995-96 Bulls', 1, '1996 RODMAN · THREAT TO HIS OWN TEAM?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('wilt-chamberlain-1967-stat-padder', '1967-wilt-padding-the-stats', 'Was 1967 Wilt padding stats against smaller centers?', 'Chases the box score in ways that do not help winning.', 'Wilt Chamberlain · 1966-67 76ers', 1, '1967 WILT · PADDING THE STATS?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
