  ('dwyane-wade-2006-championship-number-one', '2006-wade-truly-the-number-one', 'Was 2006 Finals Wade truly the Heat''s #1?', 'Good enough to be the best player on a title team.', 'Dwyane Wade · 2005-06 Heat', 1, '2006 WADE · TRULY THE #1?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('julius-randle-2021-ball-stopper', '2021-randle-ball-stopper', 'Was All-NBA Julius Randle a ball stopper?', 'The ball reaches him and the offense stops moving.', 'Julius Randle · 2020-21 Knicks', 1, '2021 RANDLE · BALL STOPPER?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
  ('chris-paul-2021-clutch', '2021-cp3-clutch-when-it-counted', 'Was Finals-run CP3 clutch when it counted?', 'You want the last shot in his hands. So does he.', 'Chris Paul · 2020-21 Suns', 1, '2021 CP3 · CLUTCH WHEN IT COUNTED?', 1, CAST(strftime('%s','now') AS INTEGER) * 1000),
